1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives the single {@code identityKey} used for all owner duplicate detection.
9	 *
10	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' +
11	 * (householdId or empty)}. A create is a duplicate only when a new owner's WHOLE
12	 * identityKey equals an existing owner's — the former separate telephone, email and
13	 * household checks are now expressed through this one key. Because the telephone is
14	 * part of the key, two members of the same household (same {@code householdId}) with
15	 * different telephones have different keys and are both allowed; only an exact
16	 * full-key match is a duplicate.
17	 *
18	 * <p>Both sides are canonicalized the same way so a new owner and the stored owners
19	 * compare on equal footing: telephone via {@link E164Telephone}, email trimmed and
20	 * lower-cased, {@code householdId} used verbatim (empty when absent).
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /** The owner's derived identity key. Never {@code null}. */
28	    public static String identityKey(Owner owner) {
29	        return telephone(owner) + "|" + email(owner) + "|" + householdId(owner);
30	    }
31	
32	    private static String telephone(Owner owner) {
33	        String e164 = E164Telephone.toE164OrNull(owner.getTelephone());
34	        if (e164 != null) {
35	            return e164;
36	        }
37	        return owner.getTelephone() == null ? "" : owner.getTelephone();
38	    }
39	
40	    private static String email(Owner owner) {
41	        String value = owner.getEmail();
42	        if (value == null) {
43	            return "";
44	        }
45	        String trimmed = value.trim();
46	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
47	    }
48	
49	    private static String householdId(Owner owner) {
50	        return owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
51	    }
52	}
