1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
7	
8	/**
9	 * The consolidated duplicate check, run after {@link AssignOwnerHousehold} (so the
10	 * deterministic {@code householdId} is set) and before {@link SaveOwner}. Duplicate
11	 * detection is expressed entirely through the {@code identityKey} (see
12	 * {@link OwnerIdentity}): a new owner is rejected as a 409 Conflict only when its whole
13	 * {@code identityKey} equals an existing owner's — an identical owner is a hard
14	 * duplicate.
15	 *
16	 * <p>Because the telephone is part of that key, two genuinely distinct members of the
17	 * same household (same computed {@code householdId} but different telephones) have
18	 * different keys and are <em>both allowed</em>: a household legitimately holds several
19	 * members, which is what the household-derived membership-level ceiling
20	 * ({@link CapOwnerMembershipLevel}) keys off. Sharing a household is therefore no longer
21	 * a conflict in itself; only an exact identity match is.
22	 *
23	 * <p>Soft-deleted owners (flagged {@code deleted}) are skipped entirely: they no longer
24	 * block a create, so a normally-blocking duplicate is admitted when the only matching
25	 * owner has been deleted.
26	 */
27	public class RejectDuplicateOwnerIdentity {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
30	            throws DuplicateOwnerIdentityException {
31	        String identityKey = OwnerIdentity.identityKey(owner);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
34	                continue; // never conflict with the owner itself
35	            }
36	            if (existing.isDeleted()) {
37	                continue; // a soft-deleted owner no longer blocks a create
38	            }
39	            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
40	                throw new DuplicateOwnerIdentityException(
41	                        "An owner with the same identity already exists");
42	            }
43	        }
44	    }
45	}
