1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (non-hard) duplicate. Runs after {@link RejectDuplicateOwnerIdentity}
10	 * has already rejected exact identity matches and undeclared household duplicates (409),
11	 * so any owner reaching this step is <em>not</em> a hard duplicate. When the new owner
12	 * nonetheless shares an existing owner's {@code lastName} (compared case-insensitively)
13	 * and {@code postcode} but with a different (normalized) telephone, the create still
14	 * proceeds and the new owner is marked as a possible duplicate: its
15	 * {@code possibleDuplicateOf} is set to the matching owner's id (the earliest such owner
16	 * when several match). Mutates the {@link Owner} in place so the value is persisted by
17	 * {@link SaveOwner} and surfaces as {@code possibleDuplicate}/{@code possibleDuplicateOf}
18	 * on the response.
19	 *
20	 * <p>A <em>declared</em> household member — one admitted through the duplicate block with
21	 * {@code sharesHousehold} — is deliberately never flagged: it shares the household by
22	 * design, so it is not a suspected duplicate.
23	 *
24	 * <p>No-ops (leaving {@code possibleDuplicateOf} null, so {@code possibleDuplicate} is
25	 * false) when the owner declared a shared household, has no postcode, or no matching
26	 * existing owner exists.
27	 */
28	public class AssignOwnerPossibleDuplicate {
29	
30	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	        String lastName = owner.getLastName();
35	        String postcode = owner.getPostcode();
36	        if (lastName == null || postcode == null || postcode.isBlank()) {
37	            return; // nothing to match on
38	        }
39	        String telephone = normalizedTelephone(owner);
40	        Owner match = null;
41	        for (Owner existing : ownerRepository.findAll()) {
42	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
43	                continue; // never match the owner against itself
44	            }
45	            if (!lastName.equalsIgnoreCase(existing.getLastName())) {
46	                continue;
47	            }
48	            if (!postcode.equals(existing.getPostcode())) {
49	                continue;
50	            }
51	            if (telephone.equals(normalizedTelephone(existing))) {
52	                continue; // same telephone would be a hard, not a possible, duplicate
53	            }
54	            if (match == null || existing.getId() < match.getId()) {
55	                match = existing; // earliest matching owner
56	            }
57	        }
58	        if (match != null) {
59	            owner.setPossibleDuplicateOf(match.getId());
60	        }
61	    }
62	
63	    /** Canonical telephone for comparison: E.164 when parseable, else the raw value. */
64	    private static String normalizedTelephone(Owner owner) {
65	        String e164 = E164Telephone.toE164OrNull(owner.getTelephone());
66	        if (e164 != null) {
67	            return e164;
68	        }
69	        return owner.getTelephone() == null ? "" : owner.getTelephone();
70	    }
71	}
