10	/**
11	 * Rejects an owner whose email domain is on the disposable-domain blocklist. Runs after
12	 * {@link NormalizeOwnerEmail}, so the email is already syntactically valid and lower-cased. When the
13	 * email is absent the owner is left untouched; when present and its domain is blocked, a 400 is
14	 * raised via {@link InvalidEmailException}.
15	 */
16	public class RejectDisposableEmailDomain {
17	
18	    private static final Set<String> BLOCKED_DOMAINS =
19	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    public void service(@Val Owner owner) throws InvalidEmailException {
22	        String email = owner.getEmail();
23	        if (email == null) {
24	            return;
25	        }
26	        int at = email.lastIndexOf('@');
27	        if (at < 0) {
28	            return;
29	        }
30	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
31	        if (BLOCKED_DOMAINS.contains(domain)) {
32	            throw new InvalidEmailException("Email domain is not allowed");
33	        }
34	    }
35	}
