10	/**
11	 * Normalizes an owner's optional email. When absent the owner is left untouched; when present the
12	 * value must be a syntactically valid address, otherwise a 400 is raised. The stored (and later
13	 * returned) value is lower-cased. Mutates the {@link Owner} in place so {@link SaveOwner} persists
14	 * the normalized value.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    public void service(@Val Owner owner) throws InvalidEmailException {
21	        String email = owner.getEmail();
22	        if (email == null) {
23	            return;
24	        }
25	        if (!EMAIL.matcher(email).matches()) {
26	            throw new InvalidEmailException("Email must be a syntactically valid address");
27	        }
28	        owner.setEmail(email.toLowerCase(Locale.ROOT));
29	    }
30	}
