7	/**
8	 * Records how many owners belong to the new owner's household once this create is
9	 * counted, i.e. the members already sharing its {@code householdId} plus the owner
10	 * being created. Runs after {@link AssignOwnerHousehold} (which sets the
11	 * {@code householdId}) and before {@link SaveOwner}, so the owner is not yet
12	 * persisted and therefore never counts itself. Mutates the {@link Owner} in place so
13	 * the snapshot is persisted for later reporting on household composition.
14	 *
15	 * <p>When the owner did not join a household (no {@code householdId}) the size is 1:
16	 * the owner is its own single-member household.
17	 */
18	public class AssignOwnerHouseholdSize {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        if (householdId == null) {
23	            owner.setHouseholdSize(1); // no shared household; a household of one
24	            return;
25	        }
26	        int count = 1; // the owner being created, not yet persisted
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
29	                continue; // never count the owner itself
30	            }
31	            if (householdId.equals(existing.getHouseholdId())) {
32	                count++;
33	            }
34	        }
35	        owner.setHouseholdSize(count);
36	    }
37	}
